<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';$db=db();$today=date('Y-m-d');$db->exec("UPDATE invoices SET status='overdue' WHERE status IN ('sent','partially_paid') AND due_date IS NOT NULL AND due_date < CURDATE() AND balance_due > 0");$q=$db->query("SELECT id,invoice_number,due_date,balance_due FROM invoices WHERE status IN ('sent','partially_paid') AND due_date IS NOT NULL AND due_date BETWEEN CURDATE() AND DATE_ADD(CURDATE(),INTERVAL 3 DAY) AND balance_due > 0");$count=0;foreach($q as $i){$count++;echo date('c')." DUE-SOON {$i['invoice_number']} due {$i['due_date']} balance {$i['balance_due']}\n";}echo date('c')." financial automation complete; due-soon={$count}\n";